import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const NhanTin = () => {
    // State lưu danh sách các phòng được chọn để gửi tin
    const [selectedRooms, setSelectedRooms] = useState([]);
    // State quản lý nội dung tin nhắn
    const [message, setMessage] = useState('');

    // Tạo danh sách 45 phòng (Tầng 1-9)
    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // Hàm chọn/bỏ chọn phòng (Chọn được nhiều cùng lúc)
    const toggleRoom = (roomId) => {
        if (selectedRooms.includes(roomId)) {
            setSelectedRooms(selectedRooms.filter(id => id !== roomId));
        } else {
            setSelectedRooms([...selectedRooms, roomId]);
        }
    };

    // Điều kiện để nút "Gửi" sáng lên: Có phòng + Có chữ
    const canSendMessage = selectedRooms.length > 0 && message.trim() !== '';

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden'
        }} className="glass-card">

            {/* Header của trang Nhắn tin */}
            <div style={{ padding: '20px', color: '#fff', borderBottom: '1px solid rgba(255,255,255,0.1)' }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Hộp thoại nhắn tin riêng</h2>
                <p style={{ margin: '5px 0 0 0', fontSize: '13px', opacity: 0.8 }}>Chọn các phòng bên dưới để gửi tin nhắn hỗ trợ</p>
            </div>

            <div style={{ flex: 1, padding: '20px', display: 'flex', gap: '20px', overflow: 'hidden' }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG ĐỂ CHỌN */}
                <div style={{ 
                    width: '230px', 
                    display: 'grid', 
                    gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', 
                    alignContent: 'flex-start', 
                    overflowY: 'auto',
                    padding: '12px',
                    backgroundColor: 'rgba(255,255,255,0.1)',
                    borderRadius: '20px'
                }}>
                    {allRooms.map(room => {
                        const isSelected = selectedRooms.includes(room);
                        return (
                            <div 
                                key={room} 
                                onClick={() => toggleRoom(room)}
                                style={{ 
                                    background: isSelected ? '#8b5e5e' : 'white', 
                                    color: isSelected ? 'white' : '#333',
                                    padding: '8px 0', 
                                    borderRadius: '8px', 
                                    textAlign: 'center', 
                                    fontSize: '11px', 
                                    fontWeight: 'bold', 
                                    cursor: 'pointer',
                                    transition: '0.2s',
                                    border: 'none',
                                    boxShadow: isSelected ? '0 4px 8px rgba(0,0,0,0.2)' : 'none'
                                }}
                            >
                                {room}
                            </div>
                        );
                    })}
                </div>

                {/* CỘT PHẢI: SOẠN TIN NHẮN */}
                <div style={{ 
                    flex: 1, 
                    display: 'flex', 
                    flexDirection: 'column', 
                    backgroundColor: 'rgba(255,255,255,0.15)', 
                    backdropFilter: 'blur(10px)',
                    borderRadius: '25px', 
                    border: '1px solid rgba(255,255,255,0.2)',
                    padding: '20px'
                }}>
                    <div style={{ flex: 1, color: '#fff' }}>
                        <div style={{ marginBottom: '15px' }}>
                            <span style={{ fontWeight: 'bold' }}>Gửi đến: </span>
                            <span style={{ 
                                background: 'rgba(255,255,255,0.2)', 
                                padding: '4px 12px', 
                                borderRadius: '15px',
                                fontSize: '14px'
                            }}>
                                {selectedRooms.length > 0 ? selectedRooms.join(', ') : 'Chưa chọn phòng'}
                            </span>
                        </div>

                        {/* Khu vực hiển thị lịch sử hoặc hướng dẫn (Tạm thời để trống) */}
                        <div style={{ 
                            height: '70%', 
                            display: 'flex', 
                            alignItems: 'center', 
                            justifyContent: 'center',
                            border: '1px dashed rgba(255,255,255,0.2)',
                            borderRadius: '15px',
                            opacity: 0.6
                        }}>
                            {selectedRooms.length === 0 
                                ? "Vui lòng chọn phòng để bắt đầu cuộc hội thoại" 
                                : `Đang soạn tin nhắn cho ${selectedRooms.length} phòng...`}
                        </div>
                    </div>

                    {/* Thanh nhập liệu */}
                    <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
                        <input 
                            style={{ 
                                flex: 1, padding: '15px', borderRadius: '15px', 
                                border: 'none', outline: 'none', fontSize: '15px' 
                            }} 
                            placeholder="Nhập nội dung tin nhắn hỗ trợ..." 
                            value={message}
                            onChange={(e) => setMessage(e.target.value)}
                        />
                        <button 
                            disabled={!canSendMessage}
                            style={{ 
                                padding: '0 30px', 
                                borderRadius: '15px', 
                                border: 'none', 
                                backgroundColor: '#8b5e5e', 
                                color: '#fff', 
                                fontWeight: 'bold',
                                opacity: canSendMessage ? 1 : 0.5,
                                cursor: canSendMessage ? 'pointer' : 'not-allowed',
                                transition: '0.3s'
                            }}
                        >
                            GỬI TIN
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default NhanTin;
